import * as THREE from 'three';
import { OrbitControls } from './vendor/OrbitControls.js';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const data=await fetch('./data.json').then(r=>{if(!r.ok)throw Error('Evidence dataset unavailable');return r.json()});
const names={USA:'United States',EU:'European Union'}, visible={USA:true,EU:true};let year=2022,selected=null,playing=null,ambient=!matchMedia('(prefers-reduced-motion: reduce)').matches;
$('motion').checked=ambient;
const docs=a=>data.filter(d=>d.actor===a&&d.year===year), score=a=>{const ds=docs(a).filter(d=>Number.isFinite(d.score));return ds.length?ds.reduce((s,d)=>s+d.score,0)/ds.length:null};
let exploring=false,flight=null;
if(innerWidth<650){document.body.classList.add('controls-collapsed');$('toggleControls').setAttribute('aria-expanded','false');$('toggleControls').querySelector('span').textContent='+';$('controlsPanel').inert=true;}
const canvas=$('universe');const view=()=>canvas.getBoundingClientRect();let renderer,scene,camera,controls,planets={},holes=[],stars,raycaster,pointer;
function seeded(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}}const random=seeded(4271);
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d'),g=x.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.16,'rgba(255,255,255,.8)');g.addColorStop(.5,'rgba(255,255,255,.12)');g.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=g;x.fillRect(0,0,128,128);return new THREE.CanvasTexture(c)}
function planetTexture(kind){const c=document.createElement('canvas');c.width=1024;c.height=512;const ctx=c.getContext('2d'),im=ctx.createImageData(1024,512);for(let y=0;y<512;y++)for(let x=0;x<1024;x++){const u=x/1024*Math.PI*2,v=y/512*Math.PI, n=Math.sin(u*6+Math.sin(v*7))*Math.cos(v*5)+.45*Math.sin(u*17-v*13)+.18*Math.cos(u*47+v*31);const clouds=Math.sin(u*21+Math.sin(v*17)*2)*Math.sin(v*27+u*3);let rgb=kind==='USA'?(n>.2?[65,111,108]:[14,54,80]):(n>.3?[125,115,151]:[36,41,78]);if(clouds>.78)rgb=rgb.map(k=>k*.55+85);const i=(y*1024+x)*4;im.data.set([...rgb,255],i)}ctx.putImageData(im,0,0);return new THREE.CanvasTexture(c)}
function blackHole(x,color){const g=new THREE.Group();g.position.set(x,0,0);const sphere=new THREE.Mesh(new THREE.SphereGeometry(1.12,64,48),new THREE.MeshBasicMaterial({color:0x010207}));g.add(sphere);const disk=new THREE.Group();disk.rotation.x=Math.PI*.39;disk.rotation.z=.1;
for(let i=0;i<9;i++){const r=1.2+i*.145,m=new THREE.Mesh(new THREE.RingGeometry(r,r+.07,128),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.55*(1-i/10),side:THREE.DoubleSide,blending:THREE.AdditiveBlending,depthWrite:false}));disk.add(m)}g.add(disk);
const halo=new THREE.Sprite(new THREE.SpriteMaterial({map:glowTexture(),color,transparent:true,opacity:.35,blending:THREE.AdditiveBlending,depthWrite:false}));halo.scale.set(7,7,1);g.add(halo);
const rim=new THREE.Mesh(new THREE.TorusGeometry(1.16,.028,12,160),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));g.add(rim);g.scale.setScalar(1.2);scene.add(g);holes.push(g);return g;}
try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(view().width,view().height,false);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x050910,.006);camera=new THREE.PerspectiveCamera(43,view().width/view().height,.1,180);controls=new OrbitControls(camera,canvas);controls.enableDamping=true;controls.dampingFactor=.065;controls.enablePan=false;controls.minDistance=15;controls.maxDistance=65;controls.maxPolarAngle=Math.PI*.78;controls.minPolarAngle=.25;scene.add(new THREE.AmbientLight(0x8eaccf,1.8));const light=new THREE.DirectionalLight(0xd1efff,3.2);light.position.set(-4,8,14);scene.add(light);const warm=new THREE.PointLight(0xf2aa70,22,28);warm.position.set(-9,1,2);scene.add(warm);const cool=new THREE.PointLight(0x72d6ff,25,25);cool.position.set(9,1,2);scene.add(cool);
const positions=new Float32Array(3600*3);for(let i=0;i<positions.length;i++)positions[i]=(random()-.5)*150;const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(positions,3));stars=new THREE.Points(geo,new THREE.PointsMaterial({color:0xb6cfdf,size:.065,transparent:true,opacity:.7,sizeAttenuation:true}));scene.add(stars);
// Thin elliptical orbit traces establish depth without encoding an extra metric.
for(let j=0;j<5;j++){const pts=[];for(let i=0;i<=160;i++){const a=i/160*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(a)*(12+j*2),-.9-j*.15,Math.sin(a)*(4+j*1.1)))}scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0x52697c,transparent:true,opacity:.13})))}
blackHole(-9,0xe5a067);blackHole(9,0x8bdfff);
for(const [i,a] of ['USA','EU'].entries()){const g=new THREE.Group(),mesh=new THREE.Mesh(new THREE.SphereGeometry(.90,64,40),new THREE.MeshStandardMaterial({map:planetTexture(a),roughness:.85,metalness:.12}));mesh.userData.actor=a;g.add(mesh);const atmosphere=new THREE.Mesh(new THREE.SphereGeometry(.95,48,32),new THREE.MeshBasicMaterial({color:a==='USA'?0x7bc6e8:0xbda7ef,transparent:true,opacity:.12,side:THREE.BackSide}));g.add(atmosphere);g.position.set(6,i===0?1.85:-1.8,i===0?1.5:0);scene.add(g);planets[a]={group:g,mesh,target:g.position.clone()}}
raycaster=new THREE.Raycaster();pointer=new THREE.Vector2();resetCamera();
}catch(e){$('notice').style.display='block';$('notice').textContent='3D is unavailable on this device. Use the actor buttons to explore the evidence.';console.error(e)}
function cameraDestination(){const aspect=view().width/view().height;return new THREE.Vector3(0,4,Math.max(23,13/(Math.tan(THREE.MathUtils.degToRad(43/2))*aspect)))}
function resizeScene(){if(!renderer)return;const r=view();camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height,false)}
function resetCamera(){if(!camera)return;flight=null;resizeScene();camera.position.copy(cameraDestination());if(!exploring)camera.position.multiplyScalar(1.16);controls.target.set(0,-.4,0);controls.enabled=exploring;controls.update()}
function enterObservatory(){exploring=true;document.body.classList.remove('landing-mode');$('workspace').inert=false;$('landing').inert=true;resizeScene();if(camera){flight={start:performance.now()-(matchMedia('(prefers-reduced-motion: reduce)').matches?1100:0),from:camera.position.clone(),to:cameraDestination()};controls.enabled=false;}setTimeout(()=>$('backHome').focus({preventScroll:true}),900)}
$('enter').onclick=enterObservatory;
function returnHome(){stop();exploring=false;document.body.classList.add('landing-mode');$('workspace').inert=true;$('landing').inert=false;resetCamera();$('enter').focus({preventScroll:true})}
$('backHome').onclick=returnHome;document.querySelector('.brand').onclick=e=>{e.preventDefault();returnHome()};
$('toggleControls').onclick=()=>{const collapsed=document.body.classList.toggle('controls-collapsed');$('toggleControls').setAttribute('aria-expanded',String(!collapsed));$('toggleControls').querySelector('span').textContent=collapsed?'+':'−';$('controlsPanel').inert=collapsed;resetCamera()};
$('reset').onclick=resetCamera;
const tmp=new THREE.Vector3();function place(id,world,dy=0){const el=$(id);if(!camera)return;tmp.copy(world).project(camera);const r=view();el.style.left=(r.left+(tmp.x+1)/2*r.width)+'px';el.style.top=(r.top+(-tmp.y+1)/2*r.height+dy)+'px';el.style.visibility=tmp.z>1?'hidden':'visible'}
function tick(){requestAnimationFrame(tick);if(!renderer)return;if(flight){const t=Math.min(1,(performance.now()-flight.start)/1100),ease=1-Math.pow(1-t,3);camera.position.lerpVectors(flight.from,flight.to,ease);if(t===1){flight=null;controls.enabled=exploring}}controls.update();const t=performance.now()/1000;for(const [a,p]of Object.entries(planets)){p.group.position.lerp(p.target,.08);if(ambient)p.mesh.rotation.y+=.0008;p.group.visible=visible[a];place('label'+a,p.group.position,45);$('label'+a).style.display=visible[a]&&$('labels').checked?'block':'none'}for(const h of holes){h.children[3]?.quaternion.copy(camera.quaternion);if(ambient)h.children[1].rotation.z=.1+Math.sin(t*.12)*.05}place('anchorR',new THREE.Vector3(-9,-2,0),25);place('anchorU',new THREE.Vector3(9,-2,0),25);if(ambient)stars.rotation.y+=.000012;renderer.render(scene,camera)}tick();
addEventListener('resize',resetCamera);
function update(){year=Number($('year').value);$('yearText').textContent=year;const count=data.filter(d=>d.year===year&&visible[d.actor]).length;$('coverage').textContent=count?`${count} source document${count===1?'':'s'} in view`:'No collected evidence for this view';$('coverageNote').textContent=year===2026?'2026 incomplete · No score carried forward':'Selected official statements';for(const a of ['USA','EU']){const s=score(a);if(planets[a]){planets[a].target.set(s===null?(a==='USA'?-1.3:1.3):s*6,s===null?-4:(a==='USA'?1.85:-1.8),a==='USA'?1.5:0);planets[a].mesh.material.color.set(s===null?0x687483:0xffffff)}}if(selected&&$('dossier').open)renderDossier();}
$('year').oninput=()=>{stop();update()};function stop(){clearInterval(playing);playing=null;$('play').textContent='▶';$('play').setAttribute('aria-label','Play timeline')}$('play').onclick=()=>{if(playing){stop();return}$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause timeline');playing=setInterval(()=>{$('year').value=year>=2026?2012:year+1;update()},1600)};
document.querySelectorAll('[data-actor]').forEach(el=>el.onchange=()=>{visible[el.dataset.actor]=el.checked;update()});$('motion').onchange=e=>ambient=e.target.checked;$('methodBtn').onclick=()=>{$('method').showModal();stop()};$('closeMethod').onclick=()=>$('method').close();$('closeDossier').onclick=()=>{$('dossier').close();selected=null};$('dossier').addEventListener('close',()=>selected=null);
function openActor(a){selected=a;stop();renderDossier();if(!$('dossier').open)$('dossier').showModal();$('tooltip').style.display='none'}for(const a of ['USA','EU'])$('label'+a).onclick=()=>openActor(a);
function renderDossier(){const a=selected,ds=docs(a),s=score(a);$('dossierYear').textContent=year;$('dossierBody').innerHTML=`<h2 class="dossier-title">${names[a]}</h2><p class="actor-desc">${a==='EU'?'European Union institutions · Institutional statements, not individual member-state positions.':'United States · Official executive-branch statements.'}</p><div class="metric-row"><div class="metric"><span>SELECTED-DOCUMENT SCORE</span><strong>${s===null?'N/A':'+'+s.toFixed(2)}</strong><small>${s===null?'Insufficient collected evidence':'Editorial source coding'}</small></div><div class="metric"><span>SOURCE COVERAGE / ${year}</span><strong>${ds.length.toString().padStart(2,'0')}</strong><small>Selected documents · Incomplete sample</small></div></div>${ds.length?`<div class="section-title">SOURCE REGISTER</div><select id="documentSelect" class="doc-select" aria-label="Select source document">${ds.map(d=>`<option value="${d.id}">${d.date} · ${esc(d.title)}</option>`).join('')}</select><div id="documentContent"></div>`:`<div class="empty">No document has been collected for this actor in ${year}. This is a collection gap, not evidence of neutrality.<div class="year-links">${[...new Set(data.filter(d=>d.actor===a).map(d=>d.year))].map(y=>`<button data-jump="${y}">${y} ↗</button>`).join('')}</div></div>`}<div class="section-title">INTERPRETATION NOTE</div><p class="tiny">The score describes the selected documents. It does not establish the actor’s complete position for this year. The current collection is small and selection-biased; scores are not suitable for ranking national policy.</p><button id="export" class="outline">↓ Export this evidence as JSON</button>`;
if(ds.length){$('documentSelect').onchange=()=>showDocument(data.find(d=>d.id===$('documentSelect').value));showDocument(ds[0])}document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{$('year').value=b.dataset.jump;update()});$('export').onclick=()=>{const blob=new Blob([JSON.stringify({actor:a,year,score:s,method:'Editorial source coding; not trained ML',documents:ds},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download=`orbit-${a}-${year}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};}
function showDocument(d){$('documentContent').innerHTML=`<article class="document"><div class="meta">${esc(d.issuer)}<br>${d.date} / ENGLISH / OFFICIAL SOURCE</div><h3>${esc(d.title)}</h3><span class="badge">${esc(d.label)} · Editorial label +1</span><p>${esc(d.summary)}</p><div class="section-title">HIGHLIGHTED SOURCE EXCERPT</div><p><mark>${esc(d.quote)}</mark></p><p class="tiny">Exact selected excerpt. Elliptical context is available in the original document.</p><a class="source-link" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Read full original document ↗</a>${d.fullText?`<div class="doc-actions"><button id="toggleFull">Read transcript here</button></div><div id="transcript" hidden><input class="doc-search" id="findText" placeholder="Find words in this transcript…" aria-label="Search transcript"><div class="fulltext" id="fullText"></div></div>`:''}</article>`;if(d.fullText){const render=q=>{const safe=esc(d.fullText);if(!q){$('fullText').innerHTML=safe.replace(esc(d.quote),`<mark>${esc(d.quote)}</mark>`);return}const needle=esc(q).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');$('fullText').innerHTML=safe.replace(new RegExp(needle,'gi'),m=>`<mark>${m}</mark>`)};render('');$('toggleFull').onclick=()=>{const el=$('transcript');el.hidden=!el.hidden;$('toggleFull').textContent=el.hidden?'Read transcript here':'Collapse transcript'};$('findText').oninput=e=>render(e.target.value)}}
let down={x:0,y:0};canvas.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});function hit(e){if(!raycaster)return null;if(!exploring)return null;const r=view();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);return raycaster.intersectObjects(Object.entries(planets).filter(([a])=>visible[a]).map(([,p])=>p.mesh))[0]?.object.userData.actor}
canvas.addEventListener('pointermove',e=>{const a=hit(e);canvas.style.cursor=a?'pointer':'grab';const tip=$('tooltip');if(!a){tip.style.display='none';return}const s=score(a);tip.innerHTML=`<span>${year} / OFFICIAL RHETORIC</span><strong>${names[a]}</strong>${s===null?'No collected evidence':`Supports Ukrainian sovereignty<br>Selected-document score: +${s.toFixed(2)}`}<br><span>${docs(a).length} source document(s) · Click for evidence</span>`;tip.style.display='block';tip.style.left=Math.min(e.clientX+18,innerWidth-255)+'px';tip.style.top=Math.min(e.clientY+18,innerHeight-150)+'px'});canvas.addEventListener('pointerleave',()=>$('tooltip').style.display='none');canvas.addEventListener('pointerup',e=>{if(Math.hypot(e.clientX-down.x,e.clientY-down.y)<6){const a=hit(e);if(a)openActor(a)}});update();
